  std::size_t solid_count = 0U;
  for (std::size_t index = 0; index < expected.size(); ++index) {
    REQUIRE(factories[index].key == expected[index]);
    if (factories[index].key == "filter/invert:inv") ++invert_count;
    if (factories[index].key == "filter/pixelSort:gatherSorted")
      ++gather_sorted_count;
    if (factories[index].key == "synth/solid:solid") ++solid_count;
    if (index > 0U) {
      // Strictly increasing everywhere except the two known dual-registered
      // pairs, where the key is permitted to repeat exactly once and no
      // other key may ever repeat.
      REQUIRE(factories[index - 1U].key <= factories[index].key);
      if (factories[index - 1U].key == factories[index].key) {
        REQUIRE((factories[index].key == "filter/invert:inv"
                 || factories[index].key == "synth/solid:solid"));
      }
    }
  }
  REQUIRE(invert_count == 2U);
