TEST(typed_task22_crt_binding_abi_is_exact) {
  const noisemaker::Surface input(1U, 1U);
  const auto bindings = [&](std::string_view skipped, std::string_view wrong) {
    noisemaker::glsl::Bindings result;
    const auto texture = [&](std::string_view name) {
      if (name == skipped) return;
      if (name == wrong) result.set_uniform(std::string(name), 1.0);
      else result.set_texture(std::string(name), input);
    };
    const auto vector2 = [&](std::string_view name, noisemaker::glsl::Vec2 value) {
      if (name == skipped) return;
      if (name == wrong) result.set_uniform(std::string(name), 1.0);
      else result.set_uniform(std::string(name), value);
    };
    const auto number = [&](std::string_view name, double value) {
      if (name == skipped) return;
      if (name == wrong) result.set_uniform(std::string(name), std::int32_t{1});
      else result.set_uniform(std::string(name), value);
    };
    const auto integer = [&](std::string_view name, std::int32_t value) {
      if (name == skipped) return;
      if (name == wrong) result.set_uniform(std::string(name), 1.0);
      else result.set_uniform(std::string(name), value);
    };
    texture("inputTex");
    vector2("resolution", noisemaker::glsl::Vec2(1.0f));
    vector2("tileOffset", noisemaker::glsl::Vec2(0.0f));
    vector2("fullResolution", noisemaker::glsl::Vec2(1.0f));
    number("time", 0.0); number("speed", 1.0); integer("seed", 1);
    number("alpha", 0.5); number("renderScale", 1.0);
    return result;
  };
  const std::array names{
      std::string_view{"inputTex"}, std::string_view{"resolution"},
      std::string_view{"tileOffset"}, std::string_view{"fullResolution"},
      std::string_view{"time"}, std::string_view{"speed"},
      std::string_view{"seed"}, std::string_view{"alpha"},
      std::string_view{"renderScale"}};
  for (const std::string_view name : names) {
    REQUIRE_THROWS_AS(noisemaker::generated::bind_filter_crt_crt(
                          bindings(name, "")),
                      noisemaker::glsl::KernelBindingError);
    REQUIRE_THROWS_AS(noisemaker::generated::bind_filter_crt_crt(
                          bindings("", name)),
                      noisemaker::glsl::KernelBindingError);
  }
  require_bind_succeeds(
      noisemaker::generated::bind_filter_crt_crt(bindings("", "")));
  noisemaker::glsl::Bindings with_extra = bindings("", "");
  with_extra.set_uniform("unrelated", 3.0);
  with_extra.set_texture("otherTex", input);
  require_bind_succeeds(
      noisemaker::generated::bind_filter_crt_crt(with_extra));
}

