TEST(task17_factories_require_exact_bindings_and_ignore_unrelated_entries) {
  const noisemaker::Surface source = noisemaker::Surface::from_rgba8(
      1U, 1U, std::array<std::uint8_t, 4>{40U, 80U, 120U, 255U});
  const noisemaker::Surface unrelated = noisemaker::Surface::from_rgba8(
      1U, 1U, std::array<std::uint8_t, 4>{1U, 2U, 3U, 4U});

  const auto bindings = [&](bool sobel, std::string_view skipped,
                            std::string_view wrong) {
    noisemaker::glsl::Bindings result;
    const auto vector = [&](std::string_view name, noisemaker::glsl::Vec2 value) {
      if (skipped == name) return;
      if (wrong == name) result.set_uniform(std::string(name), 1.0);
      else result.set_uniform(std::string(name), value);
    };
    const auto number = [&](std::string_view name, double value) {
      if (skipped == name) return;
      if (wrong == name) result.set_uniform(std::string(name), noisemaker::glsl::Vec2(1.0f));
      else result.set_uniform(std::string(name), value);
    };
    vector("tileOffset", noisemaker::glsl::Vec2(2.0f, 1.0f));
    vector("fullResolution", noisemaker::glsl::Vec2(13.0f, 11.0f));
    if (skipped != "inputTex" && wrong != "inputTex") result.set_texture("inputTex", source);
    if (wrong == "inputTex") result.set_uniform("inputTex", 1.0);
    number("amount", 1.0);
    number("renderScale", 1.0);
    if (sobel) number("alpha", 1.0);
    result.set_uniform("unrelated", 42.0);
    result.set_texture("unrelatedTex", unrelated);
    return result;
  };
  const auto bind = [](bool sobel, const noisemaker::glsl::Bindings& values) {
    return sobel ? noisemaker::generated::bind_filter_sobel_sobel(values)
                 : noisemaker::generated::bind_filter_sharpen_sharpen(values);
  };

  for (const bool sobel : {false, true}) {
    const std::array<std::string_view, 6> names{
        "tileOffset", "fullResolution", "inputTex", "amount", "renderScale", "alpha"};
    const std::size_t count = sobel ? names.size() : names.size() - 1U;
    for (std::size_t index = 0; index < count; ++index) {
      REQUIRE_THROWS_AS(bind(sobel, bindings(sobel, names[index], "")),
                        noisemaker::glsl::KernelBindingError);
      REQUIRE_THROWS_AS(bind(sobel, bindings(sobel, "", names[index])),
                        noisemaker::glsl::KernelBindingError);
    }
    require_bind_succeeds(bind(sobel, bindings(sobel, "", "")));
  }
}

