TEST(task18_factories_require_every_exact_binding_and_ignore_unrelated_entries) {
  const noisemaker::Surface source = noisemaker::Surface::from_rgba8(
      1U, 1U, std::array<std::uint8_t, 4>{40U, 80U, 120U, 255U});
  const noisemaker::Surface unrelated = noisemaker::Surface::from_rgba8(
      1U, 1U, std::array<std::uint8_t, 4>{1U, 2U, 3U, 4U});

  const auto bindings = [&](bool outline, std::string_view skipped,
                            std::string_view wrong) {
    noisemaker::glsl::Bindings result;
    const auto vector = [&](std::string_view name, noisemaker::glsl::Vec2 value) {
      if (skipped == name) return;
      if (wrong == name) result.set_uniform(std::string(name), 1.0);
      else result.set_uniform(std::string(name), value);
    };
    const auto number = [&](std::string_view name, double value) {
      if (skipped == name) return;
      if (wrong == name) {
        result.set_uniform(std::string(name), noisemaker::glsl::Vec2(1.0f));
      } else {
        result.set_uniform(std::string(name), value);
      }
    };
    const auto texture = [&](std::string_view name) {
      if (skipped == name) return;
      if (wrong == name) result.set_uniform(std::string(name), 1.0);
      else result.set_texture(std::string(name), source);
    };
    vector("tileOffset", noisemaker::glsl::Vec2(3.0f, 2.0f));
    vector("fullResolution", noisemaker::glsl::Vec2(12.0f, 10.0f));
    if (outline) {
      texture("valueTexture");
      number("sobelMetric", 3.0);
      number("thickness", 2.3);
    } else {
      texture("colorTex");
      number("edgeWidth", 2.3);
      number("edgeThreshold", 0.18);
    }
    number("renderScale", 1.0);
    result.set_uniform("unrelated", 42.0);
    result.set_texture("unrelatedTex", unrelated);
    return result;
  };
  const auto bind = [](bool outline, const noisemaker::glsl::Bindings& values) {
    return outline
               ? noisemaker::generated::bind_filter_outline_outlineSobel(values)
               : noisemaker::generated::bind_filter_celShading_celShadingEdges(values);
  };

  for (const bool outline : {false, true}) {
    const std::array cel_names{
        std::string_view{"tileOffset"}, std::string_view{"fullResolution"},
        std::string_view{"colorTex"}, std::string_view{"edgeWidth"},
        std::string_view{"edgeThreshold"}, std::string_view{"renderScale"}};
    const std::array outline_names{
        std::string_view{"tileOffset"}, std::string_view{"fullResolution"},
        std::string_view{"valueTexture"}, std::string_view{"sobelMetric"},
        std::string_view{"thickness"}, std::string_view{"renderScale"}};
    const auto& names = outline ? outline_names : cel_names;
    for (const std::string_view name : names) {
      REQUIRE_THROWS_AS(bind(outline, bindings(outline, name, "")),
                        noisemaker::glsl::KernelBindingError);
      REQUIRE_THROWS_AS(bind(outline, bindings(outline, "", name)),
                        noisemaker::glsl::KernelBindingError);
    }
    require_bind_succeeds(bind(outline, bindings(outline, "", "")));
  }
}

