TEST(typed_task25_native_table_freezes_six_cases_eleven_mutations_and_resources) {
  REQUIRE(kTask25NativeCases.size() == 6U);
  REQUIRE(kTask25LensRequiredBindings.size() == 21U);
  REQUIRE(kTask25PrismRequiredBindings.size() == 11U);
  REQUIRE(kTask25OracleTableJson.find("\"mutations\": [") !=
          std::string_view::npos);
  REQUIRE(std::count(kTask25OracleTableJson.begin(),
                     kTask25OracleTableJson.end(), '\n') > 100U);
  REQUIRE(kTask25OracleTableJson.find(
      "\"dynamic_texture_calls_per_pixel\": 3") != std::string_view::npos);
  REQUIRE(kTask25OracleTableJson.find(
      "\"texture_size_calls_per_pixel\": 0") != std::string_view::npos);
  REQUIRE(kTask25OracleTableJson.find(
      "\"texture_size_calls_per_pixel\": 1") != std::string_view::npos);
}

TEST(typed_task25_lens_and_prismatic_binding_abis_reject_every_missing_or_wrong_input) {
  for (const Task25NativeCase& fixture :
       {kTask25NativeCases[0], kTask25NativeCases[4]}) {
    const noisemaker::Surface input = task25_input(fixture);
    const noisemaker::glsl::Bindings exact =
        task25_bindings(fixture, input);
    task25_require_binding_round_trip(fixture, input, exact);
    const auto required = fixture.lens
        ? std::span<const std::string_view>(kTask25LensRequiredBindings)
        : std::span<const std::string_view>(kTask25PrismRequiredBindings);
    for (const std::string_view name : required) {
      REQUIRE_THROWS_AS(
          task25_direct_bind(
              fixture, task25_bindings(fixture, input, name)),
          noisemaker::glsl::KernelBindingError);
      REQUIRE_THROWS_AS(
          noisemaker::generated::bind(
              fixture.key, task25_bindings(fixture, input, name)),
          noisemaker::glsl::KernelBindingError);
      REQUIRE_THROWS_AS(
          task25_direct_bind(
              fixture, task25_bindings(fixture, input, {}, name)),
          noisemaker::glsl::KernelBindingError);
      REQUIRE_THROWS_AS(
          noisemaker::generated::bind(
              fixture.key, task25_bindings(fixture, input, {}, name)),
          noisemaker::glsl::KernelBindingError);
    }
    require_bind_succeeds(
        task25_direct_bind(fixture, task25_bindings(fixture, input)));
    require_bind_succeeds(noisemaker::generated::bind(
        fixture.key, task25_bindings(fixture, input)));
    require_bind_succeeds(task25_direct_bind(
        fixture, task25_bindings(fixture, input, {}, {}, true)));
    require_bind_succeeds(noisemaker::generated::bind(
        fixture.key, task25_bindings(fixture, input, {}, {}, true)));
  }
}

TEST(typed_task25_public_factory_oracles_are_exact_repeatable_finite_and_nonmutating) {
  bool all_exact = true;
  for (const Task25NativeCase& fixture : kTask25NativeCases) {
    noisemaker::Surface first_input = task25_input(fixture);
    noisemaker::Surface second_input = task25_input(fixture);
    noisemaker::Surface direct_input = task25_input(fixture);
    const auto first_input_bytes = task23_float_bytes(first_input);
    const auto second_input_bytes = task23_float_bytes(second_input);
    REQUIRE(first_input.width() == fixture.width);
    REQUIRE(first_input.height() == fixture.height);
    REQUIRE(task23_hex(task23_sha256(first_input_bytes)) ==
            fixture.input_f32_hash);
    task25_require_probes(fixture, first_input, fixture.input_probes);

    const noisemaker::Surface first = task25_render(fixture, first_input);
    const noisemaker::Surface second = task25_render(fixture, second_input);
    const noisemaker::Surface direct =
        task25_render_direct(fixture, direct_input);
    REQUIRE(first.width() == fixture.width);
    REQUIRE(first.height() == fixture.height);
    REQUIRE(second.width() == fixture.width);
    REQUIRE(second.height() == fixture.height);
    REQUIRE(direct.width() == fixture.width);
    REQUIRE(direct.height() == fixture.height);
    const auto first_f32 = task23_float_bytes(first);
    const auto first_rgba8 = first.to_rgba8();
    REQUIRE(first_f32 == task23_float_bytes(second));
    REQUIRE(first_rgba8 == second.to_rgba8());
    REQUIRE(first_f32 == task23_float_bytes(direct));
    REQUIRE(first_rgba8 == direct.to_rgba8());
    REQUIRE(task23_float_bytes(first_input) == first_input_bytes);
    REQUIRE(task23_float_bytes(second_input) == second_input_bytes);
    REQUIRE(task23_float_bytes(direct_input) == first_input_bytes);
    const std::string actual_f32_hash = task23_hex(task23_sha256(first_f32));
    const std::string actual_rgba8_hash = task23_hex(task23_sha256(first_rgba8));
    if (actual_f32_hash != fixture.output_f32_hash ||
        actual_rgba8_hash != fixture.output_rgba8_hash)
      all_exact = false;
    if (actual_f32_hash == fixture.output_f32_hash &&
        actual_rgba8_hash == fixture.output_rgba8_hash)
      task25_require_probes(fixture, first, fixture.output_probes);

    std::size_t finite_lanes = 0U;
    std::size_t nonfinite_lanes = 0U;
    for (const float value : first.data()) {
      if (std::isfinite(value))
        ++finite_lanes;
      else
        ++nonfinite_lanes;
    }
    REQUIRE(finite_lanes == fixture.finite_lanes);
    REQUIRE(nonfinite_lanes == fixture.nonfinite_lanes);
    REQUIRE(first.data().size() == fixture.width * fixture.height * 4U);
  }

  REQUIRE(all_exact);

  REQUIRE(task25_f32(kTask25NativeCases[0].number_bits[5]) < 0.0f);
  REQUIRE(task25_f32(kTask25NativeCases[1].number_bits[5]) > 0.0f);
  REQUIRE(task25_f32(kTask25NativeCases[2].number_bits[5]) < 0.0f);
  REQUIRE(task25_f32(kTask25NativeCases[3].number_bits[5]) > 0.0f);
  REQUIRE((kTask25NativeCases[4].tile_offset_bits ==
           std::array<std::uint32_t, 2>{0x00000000U, 0x00000000U}));
  REQUIRE((kTask25NativeCases[5].tile_offset_bits ==
           std::array<std::uint32_t, 2>{0x40800000U, 0x40400000U}));
  REQUIRE((kTask25NativeCases[5].full_resolution_bits ==
           std::array<std::uint32_t, 2>{0x41880000U, 0x41500000U}));
}

