// The 7 direct_relational_cases rows from the oracle, transcribed verbatim
// (left/right lane bits and every reduction/lane result the oracle records).
struct Task30RelationalRow {
  std::array<std::uint32_t, 2> left_bits, right_bits;
  std::array<bool, 2> le_lanes;
  bool all_result;
  bool any_result;
  std::array<bool, 2> strict_lanes;
};
constexpr std::array<Task30RelationalRow, 7> kTask30RelationalRows{{
    {{0x00000000U,0x00000000U}, {0x00000000U,0x00000000U}, {true,true}, true, true, {false,false}},
    {{0x3f800000U,0x40000000U}, {0x3f800000U,0x40000000U}, {true,true}, true, true, {false,false}},
    {{0x3f800000U,0x40000000U}, {0x3f800000U,0x40400000U}, {true,true}, true, true, {false,true}},
    {{0x3f800000U,0x40000000U}, {0x40000000U,0x40000000U}, {true,true}, true, true, {true,false}},
    {{0x80000000U,0x00000000U}, {0x00000000U,0x00000000U}, {true,true}, true, true, {false,false}},
    {{0xbf800000U,0x40a00000U}, {0xbf800000U,0x40800000U}, {true,false}, false, true, {false,false}},
    {{0x4b800000U,0x4b800000U}, {0x4b800000U,0x4b800000U}, {true,true}, true, true, {false,false}},
}};
