TEST(typed_task33_all_fifteen_derivative_kernels_are_registered_and_report_uses_derivatives) {
  constexpr std::array<std::pair<std::string_view, std::string_view>, 15>
      kDerivativeFactories{{
          {"filter/bulge:bulge", "bulge"},
          {"filter/celShading:celShadingColor", "celShadingColor"},
          {"filter/halftone:halftone", "halftone"},
          {"filter/lens:lens", "lens"},
          {"filter/lensWarp:lensWarp", "lensWarp"},
          {"filter/octaveWarp:octaveWarp", "octaveWarp"},
          {"filter/pinch:pinch", "pinch"},
          {"filter/polar:polar", "polar"},
          {"filter/pondRipples:pondRipples", "pondRipples"},
          {"filter/spiral:spiral", "spiral"},
          {"filter/stamp:stThreshold", "stThreshold"},
          {"filter/step:step", "step"},
          {"filter/stipple:stipple", "stipple"},
          {"filter/tunnel:tunnel", "tunnel"},
          {"filter/warp:warp", "warp"},
      }};
  const auto factories = noisemaker::generated::catalog();
  std::size_t found = 0U;
  for (const auto& [key, label] : kDerivativeFactories) {
    const auto entry = std::find_if(
        factories.begin(), factories.end(),
        [&](const noisemaker::generated::KernelFactory& item) { return item.key == key; });
    REQUIRE(entry != factories.end());
    (void)label;
    ++found;
  }
  REQUIRE(found == 15U);
  // A non-derivative program (already-landed, unaffected by this task) must
  // still report false -- the BoundKernel constructor's third argument
  // defaults false, so every pre-existing factory site is untouched.
  noisemaker::glsl::Bindings invert_bindings;
  invert_bindings.set_texture(
      "inputTex", noisemaker::Surface(1U, 1U, std::vector<float>{0.5f, 0.5f, 0.5f, 1.0f}));
  REQUIRE(!noisemaker::generated::bind_filter_invert(invert_bindings)
               .uses_derivatives());
}
