// posterize (round) / waves (any+notEqual+bvec2) -- the two derivative
// programs whose second, unrelated builtin gap (round / any+notEqual) is now
// admitted by posterize-round-admission-v1 / waves-any-notequal-admission-v1.
// Oracle vendored at docs/port-engineering/builtins/oracle/builtin-
// oracles.json (`builtin_oracle_generator.mjs`), reusing the identical
// `patternedSurface` closed-form input generator as Task 33's oracle above
// (`task33_patterned_surface`), so these cases are reproducible bit-exactly
// here too, not merely exercised with hand-controlled inputs.
TEST(typed_posterize_round_matches_vendored_oracle_bit_exact) {
  // Case "half-tie-2.5-discriminates-bankers" (phase 800): levels=2.5 is an
  // exact round-half tie. Discriminates round-half-to-even ("banker's
  // rounding", the GLSL spec's rule) from the reference JS's actual
  // Math.round (round-half-towards-+Infinity) -- round(2.5) must be 3, not
  // 2. Does NOT discriminate std::round (round-half-away-from-zero), since
  // levels_raw = max(levels, 0.0) is always non-negative and away-from-zero
  // agrees with Math.round on every non-negative real; that hazard is
  // instead proven at the exact-zero boundary by the oracle's direct rows
  // (Math.round(-0.5) === -0, out of this program's non-negative domain).
  const std::size_t width = 6U, height = 5U;
  const auto input = task33_patterned_surface(width, height, 800);
  noisemaker::glsl::Bindings direct;
  direct.set_texture("inputTex", input);
  direct.set_uniform("tileOffset", noisemaker::glsl::Vec2(0.0f, 0.0f));
  direct.set_uniform("fullResolution", noisemaker::glsl::Vec2(6.0f, 5.0f));
  direct.set_uniform("levels", 2.5f);
  direct.set_uniform("gamma", 1.2f);
  direct.set_uniform("antialias", true);
  const auto kernel = noisemaker::generated::bind_filter_posterize_posterize(direct);
  const auto first = noisemaker::run_pass(kernel, width, height);
  REQUIRE(first.data().size() == width * height * 4U);
  std::size_t finite = 0U;
  for (const float value : first.data()) {
    if (std::isfinite(value)) ++finite;
  }
  REQUIRE(finite == 120U);
  REQUIRE(task23_hex(task23_sha256(task23_float_bytes(first))) ==
          "de3da045f7e6511cba3ebdc15e27a86ba1db82ab0cee679805f1414021742da3");
  REQUIRE(task23_hex(task23_sha256(first.to_rgba8())) ==
          "024b11f0647844d469eaae4f80d0a68ea6d2b2513f50aec867a2e23793299f8e");
  struct Probe { std::size_t x, y; std::array<std::uint32_t, 4> bits; };
  const std::array<Probe, 5> probes{{
      {0U, 0U, {0x3f492942U, 0x3f54b6d0U, 0x3f2958acU, 0x3ee23b89U}},
      {5U, 0U, {0x00000000U, 0x3f2a58ebU, 0x3e15b224U, 0x3f14d653U}},
      {0U, 4U, {0x3f091c86U, 0x3f189c5cU, 0x3f4a380dU, 0x3dee23b9U}},
      {5U, 4U, {0x3ee57568U, 0x3ed0279aU, 0x3ef38262U, 0x3e82fa0cU}},
      {3U, 2U, {0x3ee6c021U, 0x3ee8689dU, 0x3ea5623cU, 0x3dbe82faU}}}};
  for (const Probe& probe : probes) {
    const std::size_t offset = (probe.y * width + probe.x) * 4U;
    for (std::size_t lane = 0; lane < 4U; ++lane) {
      REQUIRE(noisemaker::float_bits_to_uint(first.data()[offset + lane]) ==
              probe.bits[lane]);
    }
  }
  // Determinism.
  const auto second = noisemaker::run_pass(kernel, width, height);
  REQUIRE(task23_float_bytes(first) == task23_float_bytes(second));
  // Public dispatch agrees with the direct factory.
  noisemaker::glsl::Bindings via_public;
  via_public.set_texture("inputTex", input);
  via_public.set_uniform("tileOffset", noisemaker::glsl::Vec2(0.0f, 0.0f));
  via_public.set_uniform("fullResolution", noisemaker::glsl::Vec2(6.0f, 5.0f));
  via_public.set_uniform("levels", 2.5f);
  via_public.set_uniform("gamma", 1.2f);
  via_public.set_uniform("antialias", true);
  const auto public_output = noisemaker::run_pass(
      noisemaker::generated::bind("filter/posterize:posterize", via_public),
      width, height);
  REQUIRE(task23_float_bytes(first) == task23_float_bytes(public_output));
}

