TEST(typed_task35_bitwise_scalar_int_ops_oracle_cases_are_bit_exact) {
  for (const auto& fixture : kTask35BitwiseCases) {
    noisemaker::glsl::Bindings bindings;
    bindings.set_uniform("resolution", noisemaker::glsl::Vec2(
        static_cast<float>(fixture.width), static_cast<float>(fixture.height)));
    bindings.set_uniform("tileOffset", noisemaker::glsl::Vec2(
        static_cast<float>(fixture.tile_offset_x),
        static_cast<float>(fixture.tile_offset_y)));
    bindings.set_uniform("fullResolution", noisemaker::glsl::Vec2(
        static_cast<float>(fixture.full_resolution_x),
        static_cast<float>(fixture.full_resolution_y)));
    bindings.set_uniform("renderScale", fixture.render_scale);
    bindings.set_uniform("time", fixture.time);
    bindings.set_uniform("operation", fixture.operation);
    bindings.set_uniform("scale", fixture.scale);
    bindings.set_uniform("offsetX", fixture.offset_x);
    bindings.set_uniform("offsetY", fixture.offset_y);
    bindings.set_uniform("mask", fixture.mask);
    bindings.set_uniform("seed", fixture.seed);
    bindings.set_uniform("colorMode", fixture.color_mode);
    bindings.set_uniform("speed", fixture.speed);
    bindings.set_uniform("rotation", fixture.rotation);
    bindings.set_uniform("colorOffset", fixture.color_offset);

    const noisemaker::Surface rendered = noisemaker::run_pass(
        noisemaker::generated::bind_synth_bitwise_bitwise(bindings),
        fixture.width, fixture.height);

    const auto float_bytes = task23_float_bytes(rendered);
    const auto rgba_bytes = rendered.to_rgba8();
    REQUIRE(task23_hex(task23_sha256(float_bytes)) == fixture.f32_sha256);
    REQUIRE(task23_hex(task23_sha256(rgba_bytes)) == fixture.rgba8_sha256);

    // Direct catalog dispatch must agree exactly with the direct binder.
    const noisemaker::Surface via_catalog = noisemaker::run_pass(
        noisemaker::generated::bind("synth/bitwise:bitwise", bindings),
        fixture.width, fixture.height);
    REQUIRE(task23_float_bytes(via_catalog) == float_bytes);
  }
}

