TEST(typed_task35_javascript_number_boundaries_match_exact_pixel_oracles) {
  for (const auto& fixture : kTask35NumberBoundaryCases) {
    const auto bindings = task35_number_boundary_bindings(fixture);
    const noisemaker::Surface direct = noisemaker::run_pass(
        noisemaker::generated::bind_synth_bitwise_bitwise(bindings), 1U, 1U);
    REQUIRE(direct.data().size() == fixture.words.size());
    for (std::size_t lane = 0; lane < fixture.words.size(); ++lane) {
      REQUIRE(noisemaker::float_bits_to_uint(direct.data()[lane]) ==
              fixture.words[lane]);
    }
    REQUIRE(task23_hex(task23_sha256(task23_float_bytes(direct))) ==
            fixture.f32_sha256);
    REQUIRE(task23_hex(task23_sha256(direct.to_rgba8())) ==
            fixture.rgba8_sha256);

    const noisemaker::Surface catalog = noisemaker::run_pass(
        noisemaker::generated::bind("synth/bitwise:bitwise", bindings),
        1U, 1U);
    REQUIRE(task23_float_bytes(catalog) == task23_float_bytes(direct));
  }
}
