// TASK_LIGHTING_NATIVE_TESTS_BEGIN
// filter/lighting:lighting -- the one reachable `reflect(vec3,vec3)` call
// site, admitted by node identity via lighting-reflect-admission-v1
// (tools/glslcpp/frontend/reflect_admission_profile.py), plus its Sobel-
// shaped normal-map convolution (three fixed-nine local tables inside the
// `calculateNormal` helper, not `main` -- fixed_nine_table_proof.py
// generalized to a per-key host function to admit this). Oracle vendored
// from docs/port-engineering/builtins/oracle/builtin-oracles.json's
// `lighting` entry, which drives the real unmodified JS reference through
// the same deterministic `patternedSurface` input generator as Task 33 (pure
// modular arithmetic, no RNG) -- so unlike the grade cluster, this two-
// texture-input oracle IS reproducible bit-exactly here, reusing
// `task33_patterned_surface` for both `inputTex` (phase) and `heightMap`
// (phase + 300, matching `extraTextures: { heightMap: 300 }` in the
// generator). Mutation-verified by that oracle report: the sign convention
// (`I - 2*dot(N,I)*N`, no defensive internal normalize) and reachability
// (guarded by `reflection>0.0 || aberration>0.0`) both diverge under the
// documented `reflect-sign-flip` mutation and are proven live.

namespace {

struct TaskLightingCase {
  std::string_view name;
  std::size_t width, height;
  int phase;
  double tile_offset_x, tile_offset_y;
  double full_resolution_x, full_resolution_y;
  noisemaker::glsl::Vec3 diffuse_color, specular_color, ambient_color, light_direction;
  double specular_intensity, shininess, normal_strength, smoothing, render_scale;
  double reflection, refraction, aberration;
  std::string_view f32_sha256, rgba8_sha256;
  std::size_t finite_lanes;
  std::array<std::array<std::uint32_t, 4>, 5> probe_bits;
  std::array<std::array<std::size_t, 2>, 5> probe_xy;
};

void task_lighting_run(const TaskLightingCase& c) {
  // `Bindings::set_texture` stores a raw pointer to the Surface it is given
  // (glsl_runtime.cpp: `textures_.insert_or_assign(std::move(name),
  // &surface)`) -- it does NOT copy. Both Surfaces must therefore be named
  // locals that outlive every use of `bindings` below, not temporaries
  // passed inline (which would dangle the instant the full-expression ends).
  const auto input_tex =
      task33_patterned_surface(c.width, c.height, c.phase);
  const auto height_map =
      task33_patterned_surface(c.width, c.height, c.phase + 300);
  noisemaker::glsl::Bindings bindings;
  bindings.set_texture("inputTex", input_tex);
  bindings.set_texture("heightMap", height_map);
  bindings.set_uniform("tileOffset", noisemaker::glsl::Vec2(
      static_cast<float>(c.tile_offset_x), static_cast<float>(c.tile_offset_y)));
  bindings.set_uniform("fullResolution", noisemaker::glsl::Vec2(
      static_cast<float>(c.full_resolution_x), static_cast<float>(c.full_resolution_y)));
  bindings.set_uniform("diffuseColor", c.diffuse_color);
  bindings.set_uniform("specularColor", c.specular_color);
  bindings.set_uniform("specularIntensity", c.specular_intensity);
  bindings.set_uniform("shininess", c.shininess);
  bindings.set_uniform("ambientColor", c.ambient_color);
  bindings.set_uniform("lightDirection", c.light_direction);
  bindings.set_uniform("normalStrength", c.normal_strength);
  bindings.set_uniform("smoothing", c.smoothing);
  bindings.set_uniform("renderScale", c.render_scale);
  bindings.set_uniform("reflection", c.reflection);
  bindings.set_uniform("refraction", c.refraction);
  bindings.set_uniform("aberration", c.aberration);

  const auto rendered = noisemaker::run_pass(
      noisemaker::generated::bind_filter_lighting_lighting(bindings),
      c.width, c.height);
  std::size_t finite = 0U;
  for (const float value : rendered.data()) {
    if (std::isfinite(value)) ++finite;
  }
  REQUIRE(finite == c.finite_lanes);
  REQUIRE(rendered.data().size() == c.width * c.height * 4U);
  REQUIRE(task23_hex(task23_sha256(task23_float_bytes(rendered))) == c.f32_sha256);
  REQUIRE(task23_hex(task23_sha256(rendered.to_rgba8())) == c.rgba8_sha256);
  for (std::size_t index = 0; index < c.probe_xy.size(); ++index) {
    const std::size_t x = c.probe_xy[index][0];
    const std::size_t y = c.probe_xy[index][1];
    const std::size_t offset = (y * c.width + x) * 4U;
    for (std::size_t lane = 0; lane < 4U; ++lane) {
      REQUIRE(noisemaker::float_bits_to_uint(rendered.data()[offset + lane]) ==
              c.probe_bits[index][lane]);
    }
  }
  // Determinism and public-catalog-dispatch agreement.
  const auto second = noisemaker::run_pass(
      noisemaker::generated::bind_filter_lighting_lighting(bindings),
      c.width, c.height);
  REQUIRE(task23_float_bytes(rendered) == task23_float_bytes(second));
  const auto via_catalog = noisemaker::run_pass(
      noisemaker::generated::bind("filter/lighting:lighting", bindings),
      c.width, c.height);
  REQUIRE(task23_float_bytes(via_catalog) == task23_float_bytes(rendered));
}

}  // namespace

