struct StatsRuntimeCase {
  std::string_view name;
  std::size_t width;
  std::size_t height;
  int phase;
  std::array<std::size_t, 2> min_at;
  std::array<std::size_t, 2> max_at;
  bool linear;
  bool adversarial_unused;
  bool relevant_infinities;
  bool arithmetic_trap;
  std::array<std::uint32_t, 4> output_bits;
  std::array<std::uint8_t, 4> output_rgba8;
  std::string_view f32_hash;
  std::string_view rgba8_hash;
};

