  REQUIRE(diffusion[0].first_f32_index == 5U);
  REQUIRE(diffusion[0].first_rgba8_index == 5U);
  REQUIRE(diffusion[0].reference_f32_word == "0x3f2aaaab");
  REQUIRE(diffusion[0].candidate_f32_word == "0x3f800000");
  REQUIRE(diffusion[0].reference_rgba8_byte == 170U);
  REQUIRE(diffusion[0].candidate_rgba8_byte == 255U);
  REQUIRE(diffusion[1].first_f32_index == 2U);
