  REQUIRE((trace.points[0].global == std::array<float, 2>{-8.5F, 2.5F}));
  REQUIRE((trace.points[0].cell == std::array<std::int32_t, 2>{-5, 1}));
  REQUIRE((trace.points[0].block_origin == std::array<std::int32_t, 2>{-4, 0}));
  REQUIRE((trace.points[1].fragment == std::array<std::int32_t, 2>{1, 0}));
  REQUIRE((trace.points[1].global == std::array<float, 2>{-7.5F, 2.5F}));
  REQUIRE((trace.points[1].cell == std::array<std::int32_t, 2>{-4, 1}));
  REQUIRE((trace.points[1].block_origin == std::array<std::int32_t, 2>{-4, 0}));
  REQUIRE((trace.points[2].fragment == std::array<std::int32_t, 2>{5, 0}));
  REQUIRE((trace.points[2].global == std::array<float, 2>{-3.5F, 2.5F}));
  REQUIRE((trace.points[2].cell == std::array<std::int32_t, 2>{-2, 1}));
  REQUIRE((trace.points[2].block_origin == std::array<std::int32_t, 2>{0, 0}));
  REQUIRE((trace.clamp_fragment == std::array<std::int32_t, 2>{0, 0}));
  REQUIRE((trace.clamp_block_origin == std::array<std::int32_t, 2>{-4, 0}));
  REQUIRE((trace.clamp_loop_offset == std::array<std::int32_t, 2>{-4, -4}));
  REQUIRE((trace.clamp_cell == std::array<std::int32_t, 2>{-8, -4}));
  REQUIRE((trace.clamp_raw_local == std::array<std::int32_t, 2>{-6, -9}));
  REQUIRE((trace.clamp_global == std::array<float, 2>{-15.0F, -7.0F}));
  REQUIRE(trace.clamp_witness);
  REQUIRE(trace.clamp_visited);
  REQUIRE((trace.clamp_clamped == std::array<std::int32_t, 2>{0, 0}));
  REQUIRE(noisemaker_dither_oracle::kLevelEvidence.size() == 2U);
  REQUIRE(noisemaker_dither_oracle::kLevelEvidence[0].levels == 2U);
