TEST(typed_historic_palette_native_comparer_rejects_shape_length_signed_zero_and_nan_payload) {
  constexpr std::array<std::uint32_t, 4> zero_words{0U, 0U, 0U, 0U};
  constexpr std::array<std::uint8_t, 4> zero_bytes{0U, 0U, 0U, 0U};
  const historic_palette_native::ExpectedSurface expected{1U, 1U, zero_words, zero_bytes};
  const noisemaker::Surface good(1U, 1U, std::vector<float>(4U, 0.0F));
  historic_palette_native::require_exact(good, expected, "historic positive");
  REQUIRE_THROWS_AS(historic_palette_native::checked_lane_count(std::numeric_limits<std::size_t>::max(), 2U), std::runtime_error);
  REQUIRE_THROWS_AS(historic_palette_native::checked_lane_count(std::numeric_limits<std::size_t>::max() / 4U + 1U, 1U), std::runtime_error);
  const std::array<std::uint32_t, 3> short_words{0U, 0U, 0U};
  const std::array<std::uint8_t, 5> long_bytes{0U, 0U, 0U, 0U, 0U};
  REQUIRE_THROWS_AS(historic_palette_native::require_exact(good, {1U, 1U, short_words, zero_bytes}, "short"), std::runtime_error);
  REQUIRE_THROWS_AS(historic_palette_native::require_exact(good, {1U, 1U, zero_words, long_bytes}, "long"), std::runtime_error);
  const noisemaker::Surface negative_zero(1U, 1U, std::vector<float>{noisemaker::uint_bits_to_float(0x80000000U), 0.0F, 0.0F, 0.0F});
  REQUIRE_THROWS_AS(historic_palette_native::require_exact(negative_zero, expected, "signed zero"), std::runtime_error);
  const noisemaker::Surface nan_payload(1U, 1U, std::vector<float>{noisemaker::uint_bits_to_float(0x7fc12345U), 0.0F, 0.0F, 0.0F});
  const std::array<std::uint32_t, 4> other_nan{0x7fc12346U, 0U, 0U, 0U};
  REQUIRE_THROWS_AS(historic_palette_native::require_exact(nan_payload, {1U, 1U, other_nan, zero_bytes}, "NaN payload"), std::runtime_error);
}

TEST(typed_historic_palette_native_public_direct_repeat_exact_parity_and_input_lifetime) {
  REQUIRE(historic_palette_oracle::kCases.size() == 21U);
  for (const auto& fixture : historic_palette_oracle::kCases) {
    auto public_input = historic_palette_native::input_surface(fixture);
    auto direct_input = historic_palette_native::input_surface(fixture);
    auto repeat_input = historic_palette_native::input_surface(fixture);
    const auto public_before = shared_native_words(public_input);
    const auto direct_before = shared_native_words(direct_input);
    const auto repeat_before = shared_native_words(repeat_input);
    const auto public_kernel = historic_palette_native::bind_after_scope(
        [&] { return historic_palette_native::bindings(fixture, public_input); },
        [](const noisemaker::glsl::Bindings& b) { return noisemaker::generated::bind(historic_palette_oracle::kProgramKey, b); });
    const auto direct_kernel = historic_palette_native::bind_after_scope(
        [&] { return historic_palette_native::bindings(fixture, direct_input); },
        [](const noisemaker::glsl::Bindings& b) { return noisemaker::generated::bind_filter_historicPalette_historicPalette(b); });
    const auto repeat_kernel = historic_palette_native::bind_after_scope(
        [&] { return historic_palette_native::bindings(fixture, repeat_input); },
        [](const noisemaker::glsl::Bindings& b) { return noisemaker::generated::bind_filter_historicPalette_historicPalette(b); });
    const auto public_output = noisemaker::run_pass(public_kernel, fixture.width, fixture.height);
    const auto direct_output = noisemaker::run_pass(direct_kernel, fixture.width, fixture.height);
    const auto repeat_output = noisemaker::run_pass(repeat_kernel, fixture.width, fixture.height);
    const historic_palette_native::ExpectedSurface expected{fixture.width, fixture.height, fixture.f32_words, fixture.rgba8_bytes};
    historic_palette_native::require_exact(public_output, expected, std::string(fixture.name) + " public");
    historic_palette_native::require_exact(direct_output, expected, std::string(fixture.name) + " direct");
    historic_palette_native::require_exact(repeat_output, expected, std::string(fixture.name) + " repeat");
    REQUIRE(shared_native_words(public_output) == shared_native_words(direct_output));
    REQUIRE(shared_native_words(public_output) == shared_native_words(repeat_output));
    REQUIRE(public_output.data().data() != direct_output.data().data());
    REQUIRE(public_output.data().data() != repeat_output.data().data());
    REQUIRE(direct_output.data().data() != repeat_output.data().data());
    REQUIRE(public_input.data().data() != public_output.data().data());
    REQUIRE(direct_input.data().data() != direct_output.data().data());
    REQUIRE(repeat_input.data().data() != repeat_output.data().data());
    REQUIRE(shared_native_words(public_input) == public_before);
    REQUIRE(shared_native_words(direct_input) == direct_before);
    REQUIRE(shared_native_words(repeat_input) == repeat_before);
    REQUIRE(fixture.input_immutable_exact_bits);
    REQUIRE(fixture.input_surface_not_released);
    REQUIRE(fixture.input_storage_independent);
  }
}

TEST(typed_historic_palette_native_binding_abi_catalog_and_mutation_metadata) {
  constexpr std::array<std::string_view, 10> names{"inputTex", "tileOffset", "fullResolution", "paletteIndex", "rotation", "smoothness", "offset", "repeat", "alpha", "time"};
  const auto& fixture = historic_palette_oracle::kCases.front();
  auto input = historic_palette_native::input_surface(fixture);
  for (const auto name : names) {
    REQUIRE_THROWS_AS(noisemaker::generated::bind(historic_palette_oracle::kProgramKey, historic_palette_native::bindings(fixture, input, name)), noisemaker::glsl::KernelBindingError);
    REQUIRE_THROWS_AS(noisemaker::generated::bind_filter_historicPalette_historicPalette(historic_palette_native::bindings(fixture, input, name)), noisemaker::glsl::KernelBindingError);
    REQUIRE_THROWS_AS(noisemaker::generated::bind(historic_palette_oracle::kProgramKey, historic_palette_native::bindings(fixture, input, {}, name)), noisemaker::glsl::KernelBindingError);
    REQUIRE_THROWS_AS(noisemaker::generated::bind_filter_historicPalette_historicPalette(historic_palette_native::bindings(fixture, input, {}, name)), noisemaker::glsl::KernelBindingError);
  }
  const auto public_kernel = historic_palette_native::bind_after_scope([&] { return historic_palette_native::bindings(fixture, input, {}, {}, true); }, [](const noisemaker::glsl::Bindings& b) { return noisemaker::generated::bind(historic_palette_oracle::kProgramKey, b); });
  const auto direct_kernel = historic_palette_native::bind_after_scope([&] { return historic_palette_native::bindings(fixture, input, {}, {}, true); }, [](const noisemaker::glsl::Bindings& b) { return noisemaker::generated::bind_filter_historicPalette_historicPalette(b); });
  const historic_palette_native::ExpectedSurface expected{fixture.width, fixture.height, fixture.f32_words, fixture.rgba8_bytes};
  historic_palette_native::require_exact(noisemaker::run_pass(public_kernel, fixture.width, fixture.height), expected, "historic extras public");
  historic_palette_native::require_exact(noisemaker::run_pass(direct_kernel, fixture.width, fixture.height), expected, "historic extras direct");
  constexpr std::array<std::string_view, 6> mutation_names{"index-lower-clamp", "smoothness-branch", "palette-sample", "rotation-backward", "fract-scale", "alpha-mix"};
  REQUIRE(historic_palette_oracle::kMutations.size() == mutation_names.size());
  for (std::size_t i = 0U; i < mutation_names.size(); ++i) {
    REQUIRE(historic_palette_oracle::kMutations[i].name == mutation_names[i]);
    REQUIRE(historic_palette_oracle::kMutations[i].witness_count > 0U);
    REQUIRE(historic_palette_oracle::kMutations[i].anchor_occurrence_count > 0U);
  }
  const auto catalog = noisemaker::generated::catalog();
  const auto entry = std::find_if(catalog.begin(), catalog.end(), [](const auto& item) { return item.key == historic_palette_oracle::kProgramKey; });
  REQUIRE(entry != catalog.end());
  REQUIRE(entry->bind == &noisemaker::generated::bind_filter_historicPalette_historicPalette);
}

TEST(typed_palette_native_comparer_rejects_shape_length_signed_zero_and_nan_payload) {
  constexpr std::array<std::uint32_t, 4> zero_words{0U, 0U, 0U, 0U};
  constexpr std::array<std::uint8_t, 4> zero_bytes{0U, 0U, 0U, 0U};
  const palette_native::ExpectedSurface expected{1U, 1U, zero_words, zero_bytes};
  const noisemaker::Surface good(1U, 1U, std::vector<float>(4U, 0.0F));
  palette_native::require_exact(good, expected, "palette positive");
  REQUIRE_THROWS_AS(palette_native::checked_lane_count(std::numeric_limits<std::size_t>::max(), 2U), std::runtime_error);
  REQUIRE_THROWS_AS(palette_native::checked_lane_count(std::numeric_limits<std::size_t>::max() / 4U + 1U, 1U), std::runtime_error);
  const std::array<std::uint32_t, 3> short_words{0U, 0U, 0U};
  const std::array<std::uint8_t, 5> long_bytes{0U, 0U, 0U, 0U, 0U};
  REQUIRE_THROWS_AS(palette_native::require_exact(good, {1U, 1U, short_words, zero_bytes}, "short"), std::runtime_error);
  REQUIRE_THROWS_AS(palette_native::require_exact(good, {1U, 1U, zero_words, long_bytes}, "long"), std::runtime_error);
  const noisemaker::Surface negative_zero(1U, 1U, std::vector<float>{noisemaker::uint_bits_to_float(0x80000000U), 0.0F, 0.0F, 0.0F});
  REQUIRE_THROWS_AS(palette_native::require_exact(negative_zero, expected, "signed zero"), std::runtime_error);
  const noisemaker::Surface nan_payload(1U, 1U, std::vector<float>{noisemaker::uint_bits_to_float(0x7fc12345U), 0.0F, 0.0F, 0.0F});
  const std::array<std::uint32_t, 4> other_nan{0x7fc12346U, 0U, 0U, 0U};
  REQUIRE_THROWS_AS(palette_native::require_exact(nan_payload, {1U, 1U, other_nan, zero_bytes}, "NaN payload"), std::runtime_error);
}

